/*#
## Types by Example

In TJS, the example value after `:` IS the type:

| Syntax | Type |
|--------|------|
| `name: 'Alice'` | string (required) |
| `count: 42` | integer |
| `rate: 3.14` | number (float) |
| `index: +0` | non-negative integer |
| `name = 'default'` | string (optional, defaults to 'default') |
| `data: { x: 0, y: 0 }` | object with shape |
| `...nums: [0]` | rest param, array of integers |

Incidentally, you're looking at inline markdown docs...
*/

/**
 * But **jsDoc** is also supported.
 */

function greet(name: 'World'): 'Hello, World!' {
  return `Hello, ${name}!`
}

// Numeric type narrowing — all valid JS syntax
function clampIndex(index: +0, max: +0): +0 {
  return Math.min(index, max)
}

function mix(a: 0.0, b: 0.0, t: 0.0): 0.0 {
  return a + (b - a) * t
}

test 'greet says hello' {
  expect(greet('TJS')).toBe('Hello, TJS!')
}

test 'type errors are values, not exceptions' {
  const err = greet(42)
  expect(err instanceof Error).toBe(true)
}

test 'numeric types are precise' {
  expect(clampIndex(5, 10)).toBe(5)
  // negative fails non-negative integer check
  expect(clampIndex(-1, 10) instanceof Error).toBe(true)
  // float fails integer check
  expect(clampIndex(3.5, 10) instanceof Error).toBe(true)
}

test 'floats accept any number' {
  expect(mix(0, 100, 0.5)).toBe(50)
}

// Rest params — the array example IS the type
function sum(...nums: [1, 2, 3]): 6 {
  return nums.reduce((a = 0, b: 0) => a + b, 0)
}

function mean(...values: [1.0, 2.0, 3.0, 2.0]): 2.0 {
  return values.length
    ? values.reduce((sum = 0.0, x: 1.0) => sum + x) / values.length
    : 0.0
}

test 'sum integers' {
  expect(sum(1, 2, 3)).toBe(6)
}

test 'mean of floats' {
  expect(mean(10, 20, 30)).toBe(20)
}

test 'mean of empty' {
  expect(mean()).toBe(0)
}

/*#
## Required vs Optional Parameters

In TJS, the punctuation tells you everything:

| Syntax | Meaning |
|--------|---------|
| `param: 'value'` | **Required** - must be provided |
| `param = 'value'` | **Optional** - defaults to value |

The example value after `:` or `=` defines the type.
*/
test 'requires name and email' {
  const user = createUser('Alice', 'alice@test.com')
  expect(user.name).toBe('Alice')
  expect(user.age).toBe(0) // default
}

function createUser(
  name: 'anonymous',
  email: 'user@example.com',
  age = 0,
  admin = false
): { name: 'anonymous', email: 'user@example.com', age: 0, admin: false } {
  return { name, email, age, admin }
}

// Check the metadata
console.log('Params:', createUser.__tjs.params)
createUser('Alice', 'alice@example.com')

/*#
## Object Types

Object shapes are defined by example:
`{ first: '', last: '' }` means an object with string properties.

The return type `-> { x: 0, y: 0 }` is tested at transpile time!
*/
test 'createPoint returns correct structure' {
  const p = createPoint(5, 10)
  expect(p.x).toBe(5)
  expect(p.y).toBe(10)
}

function getFullName(person: { first: '', last: '' }): ' ' {
  return person.first + ' ' + person.last
}

function createPoint(x: 0, y: 0): { x: 0, y: 0 } {
  return { x, y }
}

function distance(p1: { x: 0, y: 0 }, p2: { x: 0, y: 0 }): 0 {
  const dx = p2.x - p1.x
  const dy = p2.y - p1.y
  return Math.sqrt(dx * dx + dy * dy)
}

// Usage - signature tests verify these at transpile time
const name = getFullName({ first: 'Jane', last: 'Doe' })  // -> 'Jane Doe'
const dist = distance({ x: 0, y: 0 }, { x: 3, y: 4 })     // -> 5

console.log('Name:', name)
console.log('Distance:', dist)

/*#
## Array Types

Array types use a single-element example:
- `[0]` = array of numbers
- `['']` = array of strings
- `[{ x: 0 }]` = array of objects with shape { x: number }
*/
test 'sum adds numbers' {
  expect(sum([1, 2, 3, 4])).toBe(10)
}

test 'stats calculates correctly' {
  const s = stats([10, 20, 30])
  expect(s.min).toBe(10)
  expect(s.max).toBe(30)
  expect(s.avg).toBe(20)
}

function sum(numbers: [3, 7]): 10 {
  return numbers.reduce((a, b) => a + b, 0)
}

function average(numbers: [10, 30]): 20 {
  if (numbers.length === 0) return 0
  return sum(numbers) / numbers.length
}

function stats(data: [10, 20, 30]): { min: 10, max: 30, avg: 20 } {
  if (data.length === 0) {
    return { min: 0, max: 0, avg: 0 }
  }
  return {
    min: Math.min(...data),
    max: Math.max(...data),
    avg: average(data)
  }
}

/*#
## Polymorphic Functions

Define multiple versions of a function with the same name but different
parameter signatures. TJS automatically dispatches to the right one based
on the number and types of arguments.

Like Swift/Obj-C method overloading, but at the source level.
*/

// Same name, different arities
function describe(value: 0) {
  return 'number: ' + value
}

function describe(value: '') {
  return 'string: ' + value
}

function describe(value: true) {
  return 'boolean: ' + value
}

test 'dispatch by type' {
  expect(describe(42)).toBe('number: 42')
  expect(describe('hello')).toBe('string: hello')
  expect(describe(true)).toBe('boolean: true')
}

// Different arities
function area(radius: 3.14) {
  return Math.PI * radius * radius
}

function area(width: 0.0, height: 0.0) {
  return width * height
}

test 'dispatch by arity' {
  expect(Math.round(area(1))).toBe(3)
  expect(area(3, 4)).toBe(12)
}

/*#
## What this demonstrates

Each test below names a JavaScript footgun that native TJS quietly
fixes. The test body is the proof: in raw JS the assertion would
fail, in TJS it passes. The "Test Cases" section under this paragraph
shows them in plain language.
*/

test 'Boolean(new Boolean(false)) is false' {
  expect(Boolean(new Boolean(false))).toBe(false)
}

test '!new Boolean(false) is true' {
  expect(!new Boolean(false)).toBe(true)
}

test 'new Boolean(false) is falsy in if/while/for/?:' {
  expect((new Boolean(false)) ? 'truthy' : 'falsy').toBe('falsy')
}

test 'new Boolean(false) || x returns x (LHS unwraps to falsy)' {
  expect((new Boolean(false)) || 'fallback').toBe('fallback')
}

test "'5' == 5 is false (no silent coercion across types)" {
  expect('5' == 5).toBe(false)
}

test "'' == false is false (no silent coercion)" {
  expect('' == false).toBe(false)
}

test '0 == "" is false (no silent coercion)' {
  expect(0 == '').toBe(false)
}

test 'NaN == NaN is true (NaN equals itself)' {
  expect(NaN == NaN).toBe(true)
}

test 'null == undefined is true (preserved — useful pattern)' {
  expect(null == undefined).toBe(true)
}

test 'new String("hi") == "hi" is true (boxed primitives unwrap)' {
  expect(new String('hi') == 'hi').toBe(true)
}

test 'typeof null is "null", not "object"' {
  expect(typeof null).toBe('null')
}

test 'Is({a:1}, {a:1}) is true (deep structural equality)' {
  expect(Is({ a: 1 }, { a: 1 })).toBe(true)
}

test 'Is([1,2,3], [1,2,3]) is true (arrays compare element-wise)' {
  expect(Is([1, 2, 3], [1, 2, 3])).toBe(true)
}

test 'Is(new Set([1,2]), new Set([2,1])) is true (Sets are order-independent)' {
  expect(Is(new Set([1, 2]), new Set([2, 1]))).toBe(true)
}

/*#
## Polymorphic Constructors

Classes can have multiple constructor declarations. The first becomes the
real JS constructor; the rest become factory functions that produce
correct `instanceof` results.

Classes are callable without `new` by default in native TJS, giving you
clean, expressive object creation with no directive needed.
*/

class Point {
  constructor(x: 0.0, y: 0.0) {
    this.x = x
    this.y = y
  }

  constructor(coords: { x: 0.0, y: 0.0 }) {
    this.x = coords.x
    this.y = coords.y
  }

  distanceTo(other: { x: 0.0, y: 0.0 }): 0.0 {
    const dx = this.x - other.x
    const dy = this.y - other.y
    return Math.sqrt(dx * dx + dy * dy)
  }
}

test 'construct with two numbers' {
  const p = Point(3, 4)
  expect(p.x).toBe(3)
  expect(p.y).toBe(4)
}

test 'construct with object' {
  const p = Point({ x: 10, y: 20 })
  expect(p.x).toBe(10)
  expect(p.y).toBe(20)
}

test 'methods work on both variants' {
  const a = Point(0, 0)
  const b = Point({ x: 3, y: 4 })
  expect(a.distanceTo(b)).toBe(5)
}

